async function enrollFriendInScenario(db, friendId, scenarioId) {
  const id = crypto.randomUUID();
  const now = jstNow();
  const scenarioRow = await db.prepare(`SELECT delivery_mode FROM scenarios WHERE id = ?`).bind(scenarioId).first();
  if (!scenarioRow) return null;
  const firstStep = await db.prepare(
    `SELECT step_order, delay_minutes, offset_days, offset_minutes, delivery_time
       FROM scenario_steps WHERE scenario_id = ? ORDER BY step_order ASC LIMIT 1`
  ).bind(scenarioId).first();
  if (!firstStep) {
    const result2 = await db.prepare(
      `INSERT OR IGNORE INTO friend_scenarios (id, friend_id, scenario_id, current_step_order, status, started_at, next_delivery_at, updated_at)
         VALUES (?, ?, ?, 0, 'completed', ?, NULL, ?)`
    ).bind(id, friendId, scenarioId, now, now).run();
    if (!result2.meta.changes || result2.meta.changes === 0) return null;
    return await db.prepare(`SELECT * FROM friend_scenarios WHERE id = ?`).bind(id).first();
  }
  const enrolledAtDate = new Date(Date.now() + 9 * 60 * 6e4);
  const nextDeliveryDate = computeNextDeliveryAt(
    { delivery_mode: scenarioRow.delivery_mode },
    firstStep,
    { enrolledAt: enrolledAtDate, previousDeliveredAt: enrolledAtDate, now: enrolledAtDate }
  );
  const nextDeliveryAt = nextDeliveryDate.toISOString().slice(0, -1) + "+09:00";
  const result = await db.prepare(
    `INSERT OR IGNORE INTO friend_scenarios (id, friend_id, scenario_id, current_step_order, status, started_at, next_delivery_at, updated_at)
       VALUES (?, ?, ?, -1, 'active', ?, ?, ?)`
  ).bind(id, friendId, scenarioId, now, nextDeliveryAt, now).run();
  if (!result.meta.changes || result.meta.changes === 0) return null;
  return await db.prepare(`SELECT * FROM friend_scenarios WHERE id = ?`).bind(id).first();
}
async function getFriendScenariosDueForDelivery(db, now) {
  const result = await db.prepare(
    `SELECT fs.* FROM friend_scenarios fs
       INNER JOIN scenarios s ON fs.scenario_id = s.id
       WHERE fs.status = 'active'
         AND s.is_active = 1
         AND fs.next_delivery_at IS NOT NULL`
  ).all();
  const nowMs = new Date(now).getTime();
  return result.results.filter((fs2) => new Date(fs2.next_delivery_at).getTime() <= nowMs).sort((a, b) => new Date(a.next_delivery_at).getTime() - new Date(b.next_delivery_at).getTime());
}
