function normalizeMessageType(type) {
  if (type === "carousel") return "flex";
  return type;
}
async function resolveStepContent(db, step) {
  if (!step.template_id) {
    return {
      messageType: step.message_type,
      messageContent: step.message_content,
      templateIdAtSend: null
    };
  }
  const tpl = await db.prepare("SELECT message_type, message_content FROM templates WHERE id = ?").bind(step.template_id).first();
  if (!tpl) {
    return {
      messageType: step.message_type,
      messageContent: step.message_content,
      templateIdAtSend: null
    };
  }
  return {
    messageType: normalizeMessageType(tpl.message_type),
    messageContent: tpl.message_content,
    templateIdAtSend: step.template_id
  };
}
async function getBroadcasts(db, accountId) {
  let sql = `SELECT b.*,
       bi.status as insight_status,
       bi.open_rate, bi.click_rate
FROM broadcasts b
LEFT JOIN broadcast_insights bi ON b.id = bi.broadcast_id
  AND bi.id = (SELECT id FROM broadcast_insights WHERE broadcast_id = b.id ORDER BY created_at DESC LIMIT 1)`;
  const params = [];
  if (accountId) {
    sql += ` WHERE (
      b.line_account_id = ?
      OR (
        b.target_type = 'multi-account-dedup'
        AND b.account_ids IS NOT NULL
        AND EXISTS (SELECT 1 FROM json_each(b.account_ids) WHERE value = ?)
      )
    )`;
    params.push(accountId, accountId);
  }
  sql += ` ORDER BY COALESCE(b.sent_at, b.scheduled_at, b.created_at) DESC`;
  const result = params.length > 0 ? await db.prepare(sql).bind(...params).all() : await db.prepare(sql).all();
  return result.results;
}
