function generateApiKey() {
  const bytes = new Uint8Array(16);
  crypto.getRandomValues(bytes);
  const hex2 = Array.from(bytes).map((b) => b.toString(16).padStart(2, "0")).join("");
  return `lh_${hex2}`;
}
