      await lineClient.pushMessage(lineUserId, [pushedMessage]);
      const nowIso = new Date(Date.now() + 9 * 60 * 6e4).toISOString().slice(0, -1) + "+09:00";
      const { messageToLogPayload: messageToLogPayload2 } = await Promise.resolve().then(() => stepDelivery);
      const liffLogPayload = messageToLogPayload2(pushedMessage);
