const chats = new Hono();
function clampLoadingSeconds(value) {
  const n = Number.isFinite(value) ? Math.floor(value) : 5;
  return Math.min(60, Math.max(5, n));
}
async function startLoadingAnimation(accessToken, chatId, loadingSeconds) {
  const response = await fetch("https://api.line.me/v2/bot/chat/loading/start", {
    method: "POST",
    headers: {
      Authorization: `Bearer ${accessToken}`,
      "Content-Type": "application/json"
    },
    body: JSON.stringify({ chatId, loadingSeconds })
  });
  if (!response.ok) {
    const detail = await response.text();
    throw new Error(
      detail ? `LINE API error: ${response.status} - ${detail}` : `LINE API error: ${response.status}`
    );
  }
}
async function resolveOrCreateChat(db, id) {
  const existing = await getChatById(db, id);
  if (existing) return existing;
  const friend = await getFriendById(db, id);
  if (!friend) return null;
  const byFriend = await db.prepare(`SELECT * FROM chats WHERE friend_id = ? ORDER BY created_at DESC LIMIT 1`).bind(friend.id).first();
  if (byFriend) return byFriend;
  const lastMsg = await db.prepare(
    `SELECT MAX(created_at) AS last FROM messages_log WHERE friend_id = ? AND (delivery_type IS NULL OR delivery_type != 'test')`
  ).bind(friend.id).first();
  const newId = crypto.randomUUID();
  const now = jstNow();
  const lastMessageAt = lastMsg?.last ?? null;
  await db.prepare(
    `INSERT OR IGNORE INTO chats (id, friend_id, status, last_message_at, created_at, updated_at)
       SELECT ?, ?, 'resolved', ?, ?, ?
       WHERE NOT EXISTS (SELECT 1 FROM chats WHERE friend_id = ?)`
  ).bind(newId, friend.id, lastMessageAt, now, now, friend.id).run();
  return await db.prepare(`SELECT * FROM chats WHERE friend_id = ? ORDER BY created_at DESC LIMIT 1`).bind(friend.id).first();
}
async function resolveFriendAndAccessToken(db, friendId, defaultAccessToken) {
  const friend = await getFriendById(db, friendId);
  if (!friend) {
    return { friend: null, accessToken: defaultAccessToken };
  }
  if (!friend.line_account_id) {
    return { friend, accessToken: defaultAccessToken };
  }
  const account = await getLineAccountById(db, friend.line_account_id);
  if (!account) {
    return { friend, accessToken: defaultAccessToken };
  }
  return { friend, accessToken: account.channel_access_token };
}
