const images = new Hono();
images.post("/api/images", async (c) => {
  try {
    const contentType = c.req.header("Content-Type") || "";
    let data;
    let mimeType;
    let filename;
    if (contentType.includes("application/json")) {
      const body = await c.req.json();
      if (!body.data) {
        return c.json({ success: false, error: "data (base64) is required" }, 400);
      }
      let base642 = body.data;
      if (base642.startsWith("data:")) {
        const match2 = base642.match(/^data:([^;]+);base64,(.+)$/);
        if (match2) {
          mimeType = match2[1];
          base642 = match2[2];
        }
      }
      mimeType ??= body.mimeType ?? "image/png";
      filename = body.filename;
      const binary = Uint8Array.from(atob(base642), (ch) => ch.charCodeAt(0));
      data = binary.buffer;
    } else {
      data = await c.req.arrayBuffer();
      mimeType = contentType.split(";")[0] || "image/png";
    }
    if (data.byteLength > 10 * 1024 * 1024) {
      return c.json({ success: false, error: "Image too large (max 10MB)" }, 400);
    }
    const allowedTypes = ["image/png", "image/jpeg", "image/gif", "image/webp", "application/pdf"];
    if (!allowedTypes.includes(mimeType)) {
      return c.json({ success: false, error: `Unsupported image type: ${mimeType}. Allowed: ${allowedTypes.join(", ")}` }, 400);
    }
    const ext = mimeType === "application/pdf" ? "pdf" : mimeType.split("/")[1] === "jpeg" ? "jpg" : mimeType.split("/")[1];
    const id = crypto.randomUUID();
    const key = `outgoing-${id}.${ext}`;
    await c.env.IMAGES.put(key, data, {
      httpMetadata: { contentType: mimeType },
      customMetadata: { originalFilename: filename ?? key }
    });
    const workerUrl = c.env.WORKER_URL || new URL(c.req.url).origin;
    const url = `${workerUrl}/images/${key}`;
    return c.json({
      success: true,
      data: { id, key, url, mimeType, size: data.byteLength }
    }, 201);
  } catch (err) {
    console.error("POST /api/images error:", err);
    return c.json({ success: false, error: "Internal server error" }, 500);
  }
});
images.get("/images/:key", async (c) => {
  const key = c.req.param("key");
  const object = await c.env.IMAGES.get(key);
  if (!object) {
    return c.json({ success: false, error: "Image not found" }, 404);
  }
  const headers2 = new Headers();
  headers2.set("Content-Type", object.httpMetadata?.contentType || "image/png");
  headers2.set("Cache-Control", "public, max-age=31536000, immutable");
  headers2.set("ETag", object.etag);
  return new Response(object.body, { headers: headers2 });
});
