async function buildOgForLiffPath(db, url) {
  const pathname = url.pathname;
  const liffIdFromQuery = url.searchParams.get("liffId");
  const pageFromQuery = url.searchParams.get("page");
  const idFromQuery = url.searchParams.get("id");
  const absoluteUrl = url.toString();
  const lookupAccountByLiff = async (liffId) => {
    if (!liffId) return null;
    return db.prepare(`SELECT * FROM line_accounts WHERE liff_id = ?`).bind(liffId).first();
  };
  const lookupAccountById = async (id) => {
    if (!id) return null;
    return db.prepare(`SELECT * FROM line_accounts WHERE id = ?`).bind(id).first();
  };
  let eventId = null;
  const eventPathMatch = pathname.match(/^\/events\/([^/]+)(?:\/(?:confirm|done))?\/?$/);
  if (eventPathMatch) eventId = eventPathMatch[1];
  else if (pageFromQuery === "event" && idFromQuery) eventId = idFromQuery;
  if (eventId) {
    let event = null;
    let account2 = null;
    if (liffIdFromQuery) {
      account2 = await lookupAccountByLiff(liffIdFromQuery);
      if (account2) {
        event = await db.prepare(
          `SELECT * FROM events
              WHERE id = ? AND deleted_at IS NULL AND is_published = 1 AND (
                (target_type = 'single' AND line_account_id = ?)
                OR (target_type = 'multi-account-dedup'
                    AND EXISTS (SELECT 1 FROM json_each(account_ids) WHERE value = ?))
              )`
        ).bind(eventId, account2.id, account2.id).first();
      }
    }
    if (!event && !liffIdFromQuery) {
      account2 = null;
      event = await db.prepare(
        `SELECT * FROM events WHERE id = ? AND deleted_at IS NULL AND is_published = 1`
      ).bind(eventId).first();
      if (event && event.target_type === "single" && event.line_account_id) {
        account2 = await lookupAccountById(event.line_account_id);
      }
    }
    if (event) {
      const og2 = resolveOgForEvent(event, account2, absoluteUrl);
      return buildOgHtml(og2);
    }
  }
  if (pageFromQuery === "form" && idFromQuery) {
    const form = await db.prepare(`SELECT * FROM forms WHERE id = ?`).bind(idFromQuery).first();
    if (form) {
      const account2 = await lookupAccountByLiff(liffIdFromQuery);
      const og2 = resolveOgForForm(form, account2, absoluteUrl);
      return buildOgHtml(og2);
    }
  }
  const account = await lookupAccountByLiff(liffIdFromQuery);
  const og = resolveOgForAccount(account, absoluteUrl);
  return buildOgHtml(og);
}
async function notFoundHandler(c) {
  const url = new URL(c.req.url);
  const path = url.pathname;
  if (path.startsWith("/api/") || path === "/webhook" || path === "/docs" || path === "/openapi.json") {
    return c.json({ success: false, error: "Not found" }, 404);
  }
  const ua = c.req.header("user-agent") || "";
  if (isLinkPreviewBot(ua)) {
    const html = await buildOgForLiffPath(c.env.DB, url);
    return c.html(html);
  }
  if (!c.env.ASSETS || typeof c.env.ASSETS.fetch !== "function") {
    return c.json({ success: false, error: "Not found" }, 404);
  }
  return c.env.ASSETS.fetch(c.req.raw);
}
app.notFound(notFoundHandler);
